  "#zeropsPreprocessor=on\n#\n# The Gitea project's services, as the Mate app sends them.\n#\n# Services only: no `project:` block. The app creates the project itself, tags\n# it `mate:tool:gitea` and then imports this into it, so the project keeps the\n# platform's default `envIsolation: service` — which is what stops a runner job\n# reading Gitea's admin token or the database password (ledger 2026-09-16).\n# Never set envIsolation here.\n#\n# The app replaces these placeholders before sending the file:\n#\n#   __ZEROPS_TOKEN__       the broker's Zerops token: org READ_ONLY, BASIC_USER\n#                          on this project, and BASIC_USER on each group stage\n#                          and production as they are created. Minted by the\n#                          app as the owner; the only deploy key in the account.\n#   __ZEROPS_CLIENT_ID__   the org id.\n#   __ZEROPS_PROJECT_ID__  this project's id — where the registry tags live.\n#   __MATE_APP_URL__       the web app's origin; the sign-in consent page.\n#   __REGION__             the region's name, e.g. `prg1` — what the app reads\n#                          off the new project's `publicZone`. Both shapes are\n#                          derived from it here: `api.app-{region}.zerops.io`\n#                          for the API and `{host}.{region}.zerops.app` for a\n#                          subdomain.\n#   __CORS__               every origin the Mate app runs from, comma-separated,\n#                          port included: ALLOW_DOMAIN matches a string, so\n#                          localhost does not cover 127.0.0.1 (measured\n#                          2026-09-16). The desktop and mobile shells' origins\n#                          belong here too. It is filled twice — `web` allows\n#                          those origins, the broker answers the app's own\n#                          calls with CORS for each — and the two lists are\n#                          the same list on purpose.\n#\n# `<@generateRandomString(<64>)>` is the platform's preprocessor: the value is\n# generated inside the import and never passes through the browser.\n\nservices:\n  - hostname: db\n    type: postgresql@18\n    mode: NON_HA\n    priority: 10\n\n  - hostname: volume\n    type: local-storage@1\n    priority: 10\n\n  - hostname: web\n    type: ubuntu@26.04\n    priority: 5\n    buildFromGit: https://github.com/zeropsio/gitea-mate\n    zeropsSetup: gitea\n    enableSubdomainAccess: true\n    maxContainers: 1\n    verticalAutoscaling:\n      minRam: 0.5\n    vault:\n      DB_PASSWORD:\n        value: <@generateRandomString(<64>)>\n        sensitive: true\n      GITEA_DOMAIN: web-${zeropsSubdomainHost}-3000.__REGION__.zerops.app\n      GITEA_CORS_ALLOW_DOMAIN: __CORS__\n      BROKER_PUBLIC_URL: https://broker-${zeropsSubdomainHost}-8080.__REGION__.zerops.app\n      # Gitea's client secret for the `zerops` login source. The broker\n      # generates nothing: the two services reference one another's values, so\n      # the secret exists in exactly one place.\n      OIDC_CLIENT_SECRET: ${broker_OIDC_CLIENT_SECRET}\n\n  - hostname: broker\n    type: ubuntu@26.04\n    priority: 5\n    buildFromGit: https://github.com/zeropsio/gitea-mate\n    zeropsSetup: broker\n    enableSubdomainAccess: true\n    maxContainers: 1\n    verticalAutoscaling:\n      minRam: 0.25\n    vault:\n      # docs/vocabulary.md § \"The broker's environment\", with the MATE_ prefix\n      # the platform forces on the four that name Zerops: a custom variable\n      # beginning with `ZEROPS_` is refused by the import itself\n      # (400 userDataZeropsPrefixForbidden, case-insensitive; measured\n      # 2026-09-16).\n      MATE_ZEROPS_TOKEN:\n        value: __ZEROPS_TOKEN__\n        sensitive: true\n      MATE_ZEROPS_API_URL: https://api.app-__REGION__.zerops.io\n      MATE_ZEROPS_CLIENT_ID: __ZEROPS_CLIENT_ID__\n      MATE_ZEROPS_PROJECT_ID: __ZEROPS_PROJECT_ID__\n      GITEA_URL: http://web:3000\n      GITEA_PUBLIC_URL: https://web-${zeropsSubdomainHost}-3000.__REGION__.zerops.app\n      # Gitea publishes both of these itself, on its first boot. The broker\n      # needs the password as well as the token: Gitea's token routes answer\n      # 401 \"auth required\" to an API token, however privileged (measured on\n      # 1.27.2), so minting a Mate bot's credential takes basic auth. A\n      # reference resolves in the broker's container and nowhere else — but\n      # not necessarily before the first boot: a container can start holding\n      # the literal `${…}`, so every reader treats that shape as not arrived\n      # yet (measured 2026-09-16). The broker then reads both from web's own\n      # variables through the API, and again whenever Gitea refuses them\n      # (internal/siteadmin).\n      GITEA_ADMIN_TOKEN:\n        value: ${web_GITEA_ADMIN_TOKEN}\n        sensitive: true\n      GITEA_ADMIN_PASSWORD:\n        value: ${web_GITEA_ADMIN_PASSWORD}\n        sensitive: true\n      GITEA_ADMIN_USERNAME: admin\n      GITEA_WEBHOOK_SECRET:\n        value: <@generateRandomString(<64>)>\n        sensitive: true\n      OIDC_CLIENT_SECRET:\n        value: <@generateRandomString(<64>)>\n        sensitive: true\n      # The ES256 signing key is derived from this deterministically, so a\n      # restart signs the same way and no key is ever stored.\n      OIDC_SEED:\n        value: <@generateRandomString(<64>)>\n        sensitive: true\n      BROKER_PUBLIC_URL: https://broker-${zeropsSubdomainHost}-8080.__REGION__.zerops.app\n      MATE_APP_URL: __MATE_APP_URL__\n      MATE_APP_ORIGINS: __CORS__\n      LISTEN_ADDR: :8080\n";
